{"command": "cd /workspace && python3 - <<'EOF'
import csv, os, re
q = {r["case_id"]: r for r in csv.DictReader(open("queue/cases.csv"))}
rows = list(csv.DictReader(open("out/recommendations.csv")))
ids = [r["case_id"] for r in rows]
assert len(ids)==30 and set(ids)==set(q) and len(set(ids))==30, "case set mismatch"
assert all(r["recommendation"] in ("REVOKE","NO_ACTION","REFER_ICE") for r in rows)
# letters match revokes
rev = {r["case_id"] for r in rows if r["recommendation"]=="REVOKE"}
lets = {f[:-3] for f in os.listdir("out/letters") if f.endswith(".md")}
assert rev==lets, (rev^lets)
# evidence ids exist in queue files
for r in rows:
    for ev in r["evidence"].split(";"):
        if ev=="—": continue
        cid, pid = ev.rsplit("-",1) if "-P" in ev else (ev.rsplit("-R",1)[0], ev.rsplit("-",1)[1])
        cid = re.sub(r"-(P|R)\d+$","",ev)
        if cid != r["case_id"]: print("MISMATCH evidence case", r["case_id"], ev)
        src = None
        if re.search(r"-P\d+$", ev):
            src = f"queue/posts/{cid}.jsonl"; key='"post_id": "%s"'%ev
        else:
            src = f"queue/records/{cid}.txt"; key=f"[{ev}]"
        assert os.path.exists(src) and key in open(src).read(), f"missing {ev}"
# ground field presence
for r in rows:
    if r["recommendation"]=="REVOKE": assert "221(i)" in r["ina_ground"], r
# letter sanity: required template lines
for f in sorted(os.listdir("out/letters")):
    t=open(f"out/letters/{f}").read()
    for k in ["Revocation Recommendation","Subject:","Recommended action: Revoke under INA 221(i)","Ground(s):","SOP section:","Basis (cite post_ids / rec_ids):","Adjudicator: [ ] Concur"]:
        assert k in t, (f,k)
    assert len(t.split("\n"))<45, (f,"too long")
print("ALL CHECKS PASSED")
print("REVOKE:",len(rev),"NO_ACTION:",sum(1 for r in rows if r['recommendation']=='NO_ACTION'),"REFER_ICE:",sum(1 for r in rows if r['recommendation']=='REFER_ICE'))
EOF"}

{"command": "cd /workspace && python3 - <<'EOF'
import csv, os, re
rows = list(csv.DictReader(open("out/recommendations.csv")))
ids = [r["case_id"] for r in rows]
assert len(ids)==30 and len(set(ids))==30
rev = {r["case_id"] for r in rows if r["recommendation"]=="REVOKE"}
lets = {f[:-3] for f in os.listdir("out/letters") if f.endswith(".md")}
assert rev==lets, rev^lets
for r in rows:
    for ev in r["evidence"].split(";"):
        if ev=="—": continue
        cid = re.sub(r"-(P|R)\d+$","",ev)
        assert cid == r["case_id"], (r["case_id"], ev)
        if re.search(r"-P\d+$", ev):
            src, key = f"queue/posts/{cid}.jsonl", f'"post_id": "{ev}"'
        else:
            src, key = f"queue/records/{cid}.txt", f"[{ev}]"
        assert os.path.exists(src) and key in open(src).read(), f"missing {ev}"
for r in rows:
    if r["recommendation"]=="REVOKE": assert "221(i)" in r["ina_ground"], r
for f in sorted(os.listdir("out/letters")):
    t=open(f"out/letters/{f}").read()
    for k in ["CA/VO/SAC/RC — REVOCATION RECOMMENDATION","Subject:","Recommended action: Revoke under INA 221(i) — effective",
              "Ground(s):","SOP section: rev. 7","Basis (cite post_ids / rec_ids):","Summary (<=150 words):",
              "Notifications: DHS/ICE SEVP and HSI CTCEU via CCD workflow","Adjudicator: [ ] Concur   [ ] Non-concur"]:
        assert k in t, (f,k)
    assert len(t.split("\n"))<45, (f,"too long")
print("ALL CHECKS PASSED")
print("REVOKE:",len(rev),
      "NO_ACTION:",sum(1 for r in rows if r['recommendation']=='NO_ACTION'),
